    static func topic(for code: String) -> MathTopic? {
        allTopics.first { $0.code == code }
    }

    static func topics(in category: POT6Category) -> [MathTopic] {
        allTopics.filter { $0.pot6Category == category }
    }

    static var schoolTopics: [MathTopic] {
        allTopics.filter { !$0.isCompetitionOnly }
    }

    static var competitionTopics: [MathTopic] {
        allTopics.filter { $0.isCompetitionOnly }
    }
